// LinkedIn — implement a hash map from scratch (LeetCode 706 shape), then resizing, then thread safety.
// No Dictionary inside. Separate chaining with singly linked nodes.
public sealed class IntHashMap {
    sealed class Node { public int Key; public int Value; public Node Next; }
    Node[] _buckets;
    int _count;
    const double MaxLoad = 0.75;

    public IntHashMap(int capacity = 16) => _buckets = new Node[Math.Max(4, capacity)];
    public int Count => _count;
    public int Capacity => _buckets.Length;

    // Spread the bits so keys that differ only in high bits do not collide (e.g. multiples of the size).
    static int Index(int key, int size) { uint h = (uint)key * 0x9E3779B1u; return (int)(h >> 1) % size; }

    public void Put(int key, int value) {
        int i = Index(key, _buckets.Length);
        for (var n = _buckets[i]; n != null; n = n.Next) if (n.Key == key) { n.Value = value; return; }
        _buckets[i] = new Node { Key = key, Value = value, Next = _buckets[i] };
        if (++_count > _buckets.Length * MaxLoad) Resize();
    }

    public bool TryGet(int key, out int value) {
        for (var n = _buckets[Index(key, _buckets.Length)]; n != null; n = n.Next)
            if (n.Key == key) { value = n.Value; return true; }
        value = 0; return false;
    }

    public int Get(int key) => TryGet(key, out var v) ? v : -1;      // the LeetCode contract

    public bool Remove(int key) {
        int i = Index(key, _buckets.Length);
        Node prev = null;
        for (var n = _buckets[i]; n != null; prev = n, n = n.Next) {
            if (n.Key != key) continue;
            if (prev == null) _buckets[i] = n.Next; else prev.Next = n.Next;
            _count--; return true;
        }
        return false;
    }

    // Double and rehash: amortised O(1) per Put.
    void Resize() {
        var old = _buckets; _buckets = new Node[old.Length * 2];
        foreach (var head in old)
            for (var n = head; n != null; ) {
                var next = n.Next; int i = Index(n.Key, _buckets.Length);
                n.Next = _buckets[i]; _buckets[i] = n; n = next;
            }
    }
}

// Stage 3: thread-safe by striping — N independent maps, a key always goes to the same stripe.
public sealed class StripedIntHashMap {
    readonly IntHashMap[] _maps; readonly object[] _locks;
    public StripedIntHashMap(int stripes = 16) {
        _maps = Enumerable.Range(0, stripes).Select(_ => new IntHashMap()).ToArray();
        _locks = Enumerable.Range(0, stripes).Select(_ => new object()).ToArray();
    }
    int S(int key) => (int)((uint)key * 2654435761u % (uint)_maps.Length);
    public void Put(int key, int value) { int s = S(key); lock (_locks[s]) _maps[s].Put(key, value); }
    public int Get(int key) { int s = S(key); lock (_locks[s]) return _maps[s].Get(key); }
    public bool Remove(int key) { int s = S(key); lock (_locks[s]) return _maps[s].Remove(key); }
    public void AddOrIncrement(int key, int by) { int s = S(key); lock (_locks[s]) { var m = _maps[s]; m.Put(key, (m.TryGet(key, out var v) ? v : 0) + by); } }
    public int Count { get { int c = 0; for (int s = 0; s < _maps.Length; s++) lock (_locks[s]) c += _maps[s].Count; return c; } }
}
